// ── Throwaway coupon codes ──────────────────────────────────────────────────
// The verification code is generated by the SAME function as production codes
// (src/lib/coupon-code.ts: same separators, same per-provider length/charset
// rules, same random suffix), so a provider that accepts it will accept real
// codes. Only the prefix and country are fixed to obviously-throwaway values.

import { generateCouponCode, type RandomBytes } from '../../src/lib/coupon-code';

export {
  ALNUM_ONLY_PROVIDERS,
  CODE_MAX_LENGTH,
  SUFFIX_CHARS,
  SUFFIX_LENGTH,
  generateCouponCode,
  type RandomBytes,
} from '../../src/lib/coupon-code';

/** Prefix that marks a code as created by this tool. */
export const VERIFY_PREFIX = 'VERIFY';
/** ISO 3166-1 user-assigned code: never a real country. */
export const VERIFY_COUNTRY = 'ZZ';

/** e.g. VERIFY-ZZ17-K7QX (Chargebee), VERIFYZZ17K7QX (Stripe/Paddle/Polar). */
export function generateThrowawayCode(
  provider: string,
  percent: number,
  randomBytes?: RandomBytes,
): string {
  return generateCouponCode(VERIFY_COUNTRY, percent, VERIFY_PREFIX, provider, randomBytes);
}
